      ('cam-bien-quang-autonics-bj', 'cam-bien-quang'),
      ('nguon-autonics-spb', 'bo-nguon'),
      ('encoder-autonics-e50s', 'encoder'),
      ('bo-dieu-khien-tu-bu-mikro', 'bo-dieu-khien-tu-bu'),
      ('relay-bao-ve-mikro', 'relay-bao-ve'),
      ('cau-chi-nh-eaton-bussmann', 'cau-chi-ha-the'),
      ('cau-chi-ban-dan-eaton-bussmann', 'cau-chi-ha-the'),
      ('cau-chi-ong-10x38-bussmann', 'cau-chi-ha-the'),
      ('de-cau-chi-gan-ray', 'de-cau-chi'),
      ('tu-bu-ha-the', 'tu-bu'),
      ('cuon-khang-loc-song-hai', 'cuon-khang'),
      ('encoder-cong-nghiep', 'encoder'),
      ('den-bao-pha-ad16', 'den-bao-nut-nhan'),
      ('den-thap-tin-hieu', 'den-bao-nut-nhan'),
      ('cong-tac-xoay', 'den-bao-nut-nhan'),
      ('cong-tac-chia-khoa', 'den-bao-nut-nhan'),
      ('hop-nut-nhan-cau-truc', 'den-bao-nut-nhan')
    ) as v(product_slug, category_slug)
    join public.categories c on c.slug = v.category_slug
    where pr.slug = v.product_slug
      and (pr.category_id is null or pr.category_id in (select id from public.categories where parent_id is null));
    
    -- The old flat group 'Thiết bị điện công nghiệp' is replaced by the new groups; drop it once empty.
    delete from public.categories old where old.slug = 'thiet-bi-dien-cong-nghiep'
      and not exists (select 1 from public.products where category_id = old.id)
      and not exists (select 1 from public.categories where parent_id = old.id);
  else
    raise notice 'Bỏ qua dữ liệu mẫu "categories": hãy chạy 0007_category_tree.sql trước, rồi chạy lại seed.sql';
  end if;
end
$seed$;

