do $seed$
begin
  if to_regclass('public.products') is not null
     and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'products' and column_name = 'specs')
     and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'products' and column_name = 'image_url')
     and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'products' and column_name = 'in_stock') then
    insert into public.products (slug, name, category_id, brand_id, summary, description, specs, image_url, featured, published, in_stock) values
      ('plc-siemens-s7-1200', 'Bộ lập trình PLC Siemens S7-1200', (select id from public.categories where slug = 'plc'), (select id from public.brands where slug = 'siemens'), 'PLC nhỏ gọn cho các ứng dụng điều khiển máy và dây chuyền vừa và nhỏ.', 'Dòng PLC S7-1200 tích hợp cổng PROFINET, lập trình bằng TIA Portal. Liên hệ để được tư vấn chọn CPU, module mở rộng và báo giá.', 'Dòng sản phẩm | S7-1200
    Ngôn ngữ lập trình | LAD, FBD, SCL (TIA Portal)
    Cổng truyền thông | PROFINET tích hợp
    Nguồn cấp | 24 VDC hoặc 120/230 VAC (tùy CPU)
    Mở rộng | Signal board, signal module, communication module', '/img/sp/plc-siemens-s7-1200.jpg', true, true, true),
      ('bien-tan-mitsubishi-fr-e800', 'Biến tần Mitsubishi FR-E800', (select id from public.categories where slug = 'bien-tan'), (select id from public.brands where slug = 'mitsubishi-electric'), 'Biến tần đa năng cho bơm, quạt, băng tải.', 'Biến tần FR-E800 hỗ trợ nhiều chuẩn truyền thông công nghiệp. Liên hệ để được tư vấn công suất phù hợp.', null, '/demo/bien-tan.svg', false, true, true),
      ('cam-bien-tiem-can-omron', 'Cảm biến tiệm cận Omron', (select id from public.categories where slug = 'cam-bien-tiem-can'), (select id from public.brands where slug = 'omron'), 'Cảm biến tiệm cận điện cảm, nhiều kích thước M8 – M30.', 'Phát hiện vật thể kim loại không tiếp xúc, dùng trong máy đóng gói, băng tải, máy CNC.', null, '/demo/cam-bien-tiem-can.svg', false, true, true),
      ('aptomat-schneider-easy9', 'Aptomat (MCB) Schneider Easy9', (select id from public.categories where slug = 'mcb'), (select id from public.brands where slug = 'schneider-electric'), 'Cầu dao tự động bảo vệ quá tải và ngắn mạch.', 'Đầy đủ dòng định mức và số cực. Liên hệ để nhận báo giá theo số lượng.', null, '/img/sp/aptomat-schneider-easy9.jpg', true, true, true),
      ('contactor-abb-af', 'Contactor ABB dòng AF', (select id from public.categories where slug = 'contactor'), (select id from public.brands where slug = 'abb'), 'Khởi động từ cho động cơ và tải công nghiệp.', 'Cuộn coil dải điện áp rộng, độ bền cao. Liên hệ để được tư vấn chọn mã.', null, '/img/sp/contactor-abb-af.jpg', false, true, true),
      ('xi-lanh-khi-nen-festo', 'Xi lanh khí nén Festo', (select id from public.categories where slug = 'xi-lanh-khi-nen'), (select id from public.brands where slug = 'festo'), 'Xi lanh tiêu chuẩn ISO, nhiều đường kính và hành trình.', 'Phù hợp cho các ứng dụng gá kẹp, đẩy, nâng hạ trong dây chuyền tự động.', null, '/demo/xi-lanh-khi-nen.svg', false, true, true),
      ('van-dien-tu-smc', 'Van điện từ khí nén SMC', (select id from public.categories where slug = 'van-dien-tu-khi-nen'), (select id from public.brands where slug = 'smc'), 'Van điện từ 5/2, 5/3 điều khiển xi lanh khí nén.', 'Đa dạng điện áp coil và kiểu kết nối. Liên hệ để được báo giá nhanh.', null, '/demo/van-dien-tu.svg', false, true, true),
      ('cam-bien-quang-sick', 'Cảm biến quang SICK', (select id from public.categories where slug = 'cam-bien-quang'), (select id from public.brands where slug = 'sick'), 'Cảm biến quang thu phát, phản xạ gương và phản xạ khuếch tán.', 'Độ chính xác cao, phù hợp cho môi trường công nghiệp khắc nghiệt.', null, '/img/sp/cam-bien-quang-sick.jpg', false, true, true),
      ('motor-giam-toc', 'Motor giảm tốc công nghiệp', (select id from public.categories where slug = 'motor-giam-toc'), null, 'Motor giảm tốc cốt thẳng, cốt vuông góc nhiều tỉ số truyền.', 'Tư vấn chọn công suất, tỉ số truyền và kiểu lắp đặt theo yêu cầu thực tế.', null, '/img/sp/motor-giam-toc.jpg', true, true, true),
      ('van-bi-inox', 'Van bi inox', (select id from public.categories where slug = 'van-bi'), null, 'Van bi inox nối ren, mặt bích các cỡ.', 'Dùng cho hệ thống nước, khí, hóa chất nhẹ. Cung cấp kèm co, tê, rắc co đồng bộ.', null, '/demo/van-bi-inox.svg', false, true, true),
      ('plc-siemens-s7-200-smart', 'PLC Siemens S7-200 SMART', (select id from public.categories where slug = 'plc'), (select id from public.brands where slug = 'siemens'), 'Cung cấp PLC Siemens S7-200 SMART cho nhà máy và tủ điện công nghiệp. Tư vấn chọn mã đúng thông số, báo giá nhanh.', 'Đạt Danh cung cấp PLC Siemens S7-200 SMART cho nhà máy, xưởng sản xuất và tủ điện công nghiệp.
    
